549	/**
550	 * POST /ai-curriculum/incremental/:buildId/generate-stage
551	 *
552	 * Generates content for the next stage (or a specified stage index).
553	 * Synchronous AI call (~15-25s). Returns the generated stage for review.
554	 * Body: { stageIdx?: number } — defaults to build.currentStageIdx
555	 */
556	aiCurriculumIncremental.post(
557	  '/ai-curriculum/incremental/:buildId/generate-stage',
558	  requireAuth(),
559	  async (c) => {
560	    const apiKey = getAnthropicKey('curriculum-incremental-revise');
561	    if (!apiKey) {
562	      return c.json({ error: 'AI service not configured' }, 503);
563	    }
564	
565	    const buildId = c.req.param('buildId')!;
566	    const authUser = c.get('authUser') as AuthUser;
567	    const orgId = await resolveOrgIdFromSession(authUser, c);
568	    if (!orgId) return c.json({ error: 'Could not resolve organization' }, 403);
569	
570	    let body: { stageIdx?: number } = {};
571	    try {
572	      body = await c.req.json();
573	    } catch {
574	      // empty body is fine
575	    }
576	
577	    const [build] = await db
578	      .select()
579	      .from(curriculumIncrementalBuilds)
580	      .where(
581	        and(
582	          eq(curriculumIncrementalBuilds.id, buildId),
583	          eq(curriculumIncrementalBuilds.flightSchoolId, orgId),
584	        ),
585	      )
586	      .limit(1);
587	
588	    if (!build) return c.json({ error: 'Build not found' }, 404);
589	
590	    const outline = build.outline as GeneratedOutline | null;
591	    if (!outline?.stages || outline.stages.length === 0) {
592	      return c.json({ error: 'Outline not yet approved' }, 400);
593	    }
594	
595	    const stageIdx = body.stageIdx ?? build.currentStageIdx;
596	    if (stageIdx >= outline.stages.length) {
597	      return c.json({ error: 'Stage index out of range' }, 400);
598	    }
599	
600	    const targetStage = outline.stages[stageIdx];
601	    const params = build.builderParams as BuilderParams;
602	    const approvedStages = (build.approvedStages ?? []) as unknown[];
603	    const approvedStageNames = (outline.stages as OutlineStage[])
604	      .slice(0, stageIdx)
605	      .map((s) => s.name);
606	
607	    // Generate stage content synchronously (~15-25s)
608	    const prompt = buildStagePrompt(
609	      params,
610	      stageIdx,
611	      targetStage.name,
612	      targetStage.description,
613	      approvedStageNames,
614	    );
615	
616	    let aiResult: { text: string; inputTokens: number; outputTokens: number };
617	    try {
618	      aiResult = await callClaude(apiKey, prompt, 8000);
619	    } catch (err) {
620	      const msg =
621	        err instanceof Error
622	          ? err.message
623	          : typeof err === 'object' && err !== null
624	            ? JSON.stringify(err)
625	            : String(err);
626	      return c.json({ error: `AI generation failed: ${msg}` }, 500);
627	    }
628	
629	    void recordAiTokenUsage({
630	      feature: 'curriculum_incremental_stage',
631	      flightSchoolId: orgId,
632	      inputTokens: aiResult.inputTokens,
633	      outputTokens: aiResult.outputTokens,
634	    });
635	
636	    const cleaned = stripCodeFences(aiResult.text);
637	    const parsed = safeParseAIJson<{ name?: string; modules?: unknown[] }>(
638	      cleaned,
639	    );
640	
641	    if (!parsed || !Array.isArray(parsed.modules)) {
642	      return c.json(
643	        { error: 'AI returned an invalid stage structure — please try again' },
644	        500,
645	      );
646	    }
647	
648	    const stageWithIds = addCurriculumIds([
649	      {
