666	/**
667	 * POST /ai-curriculum/incremental/:buildId/approve-stage
668	 *
669	 * Saves an admin-reviewed (and optionally edited) stage to DB.
670	 * Body: { stageIdx: number, stage: object }
671	 */
672	aiCurriculumIncremental.post(
673	  '/ai-curriculum/incremental/:buildId/approve-stage',
674	  requireAuth(),
675	  async (c) => {
676	    const buildId = c.req.param('buildId')!;
677	    const authUser = c.get('authUser') as AuthUser;
678	    const orgId = await resolveOrgIdFromSession(authUser, c);
679	    if (!orgId) return c.json({ error: 'Could not resolve organization' }, 403);

680	
681	    let body: { stageIdx: number; stage: unknown };
682	    try {
683	      body = await c.req.json();
684	    } catch {
685	      return c.json({ error: 'Invalid request body' }, 400);
686	    }
687	
688	    if (typeof body.stageIdx !== 'number' || !body.stage) {
689	      return c.json({ error: 'stageIdx and stage are required' }, 400);
690	    }
691	
692	    const [build] = await db
693	      .select()
694	      .from(curriculumIncrementalBuilds)
695	      .where(
696	        and(
697	          eq(curriculumIncrementalBuilds.id, buildId),
698	          eq(curriculumIncrementalBuilds.flightSchoolId, orgId),
699	        ),
700	      )
701	      .limit(1);
702	
703	    if (!build) return c.json({ error: 'Build not found' }, 404);
704	
705	    const outline = build.outline as GeneratedOutline | null;
706	    if (!outline?.stages) return c.json({ error: 'Outline not approved' }, 400);
707	
708	    // Splice the approved stage into the array at the correct index
709	    const currentStages = ((build.approvedStages ?? []) as unknown[]).slice();
710	    currentStages[body.stageIdx] = body.stage;
711	
712	    const nextIdx = body.stageIdx + 1;
713	    const isComplete = nextIdx >= outline.stages.length;
714	    const newStatus = isComplete ? 'outline_approved' : 'outline_approved';
715	    // Status remains outline_approved until publish; we track progress via currentStageIdx
716	
717	    await db
718	      .update(curriculumIncrementalBuilds)
719	      .set({
720	        approvedStages: currentStages as never,
721	        currentStageIdx: nextIdx,
722	        status: newStatus,
723	        updatedAt: new Date(),
724	      })
725	      .where(eq(curriculumIncrementalBuilds.id, buildId));
726	
727	    return c.json({
728	      success: true,
729	      nextStageIdx: nextIdx,
730	      isComplete,
731	      approvedCount: currentStages.filter(Boolean).length,
732	    });
733	  },
734	);
